import React, { useState } from 'react';
import { 
  Typography, 
  Card, 
  Tabs, 
  Space, 
  Button, 
  Switch, 
  Select, 
  Input,
  Form,
  Row,
  Col,
  Divider,
  Alert,
  Tag,
  Avatar,
  App
} from 'antd';
import { 
  UserOutlined, 
  SettingOutlined, 
  BellOutlined, 
  SecurityScanOutlined,
  GlobalOutlined,
  RobotOutlined,
  CreditCardOutlined,
  LockOutlined,
  EyeOutlined,
  EyeInvisibleOutlined,
  BgColorsOutlined
} from '@ant-design/icons';
import UserProfile from '../components/UserProfile';
import ThemeEditor from '../components/ThemeEditor';

const { Title, Text, Paragraph } = Typography;
const { Option } = Select;
const { TabPane } = Tabs;

interface SettingsProps {
  prompts?: any[]; // Добавляем промпты для передачи в UserProfile
}

const Settings: React.FC<SettingsProps> = ({ prompts = [] }) => {
  const [activeTab, setActiveTab] = useState('profile');
  const [showPassword, setShowPassword] = useState(false);

  const handleTabChange = (key: string) => {
    setActiveTab(key);
  };

  const openDebugTool = () => {
    const debugUrl = '/debug-auth.html';
    window.open(debugUrl, '_blank', 'width=1000,height=800,scrollbars=yes,resizable=yes');
  };

  return (
    <div className="container settings-page" style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%', overflowX: 'hidden' }}>
      <div className="soulpulse-header" style={{ marginBottom: 'var(--sp-spacing-sm)' }}>
        <Title className="soulpulse-title" style={{ margin: 0 }}>
          <SettingOutlined style={{ marginRight: 'var(--sp-spacing-sm)' }} />
          Настройки приложения
        </Title>
        <Text className="soulpulse-subtitle" style={{ opacity: 0.8 }}>
          Управление профилем, безопасностью и предпочтениями
        </Text>
      </div>

      <Tabs 
        activeKey={activeTab} 
        onChange={handleTabChange}
        size="large"
        style={{}}
        items={[
          {
            key: 'profile',
            label: (
              <span>
                <UserOutlined />
                Профиль
              </span>
            ),
            children: <UserProfile prompts={prompts} />
          },
          {
            key: 'preferences',
            label: (
              <span>
                <SettingOutlined />
                Предпочтения
              </span>
            ),
            children: <PreferencesTab />
          },
          {
            key: 'security',
            label: (
              <span>
                <SecurityScanOutlined />
                Безопасность
              </span>
            ),
            children: <SecurityTab />
          },
          {
            key: 'notifications',
            label: (
              <span>
                <BellOutlined />
                Уведомления
              </span>
            ),
            children: <NotificationsTab />
          },
          {
            key: 'ai-settings',
            label: (
              <span>
                <RobotOutlined />
                AI настройки
              </span>
            ),
            children: <AISettingsTab />
          },
          {
            key: 'themes',
            label: (
              <span>
                <BgColorsOutlined />
                Темы
              </span>
            ),
            children: (
              <App>
                <ThemeEditor />
              </App>
            )
          },
          {
            key: 'debug',
            label: (
              <span>
                <SecurityScanOutlined />
                Debug
              </span>
            ),
            children: <DebugTab openDebugTool={openDebugTool} />
          }
        ]}
      />
    </div>
  );
};

// Остальные вкладки без инлайн-хардкодов цветов
// Вкладка предпочтений
const PreferencesTab: React.FC = () => {
  const [form] = Form.useForm();

  const onFinish = (values: any) => {
    console.log('Предпочтения сохранены:', values);
  };

  return (
    <div style={{ padding: 'var(--sp-spacing-xs)' }}>
      <Title level={3} style={{ marginTop: 0 }}>Настройки интерфейса</Title>
      
      <Form
        form={form}
        layout="vertical"
        onFinish={onFinish}
        initialValues={{
          language: 'ru',
          theme: 'auto',
          compactMode: false,
          showAnimations: true
        }}
      >
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Язык интерфейса" name="language">
              <Select>
                <Option value="ru">Русский</Option>
                <Option value="en">English</Option>
                <Option value="de">Deutsch</Option>
                <Option value="fr">Français</Option>
              </Select>
            </Form.Item>
          </Col>
          
          <Col xs={24} md={12}>
            <Form.Item label="Тема оформления" name="theme">
              <Select 
                popupMatchSelectWidth 
                onChange={(value) => {
                if (value === 'auto') {
                  localStorage.removeItem('sp_theme');
                } else {
                  localStorage.setItem('sp_theme', value);
                }
                window.dispatchEvent(new CustomEvent('theme-changed', { detail: value }));
                const bodyEl = document.body as HTMLElement;
                if (bodyEl) {
                  bodyEl.classList.remove('theme-dark-indigo','theme-dark-slate','theme-light-indigo');
                  if (value !== 'auto') bodyEl.classList.add(value);
                }
              }}>
                <Option value="auto">Автоматически</Option>
                <Option value="theme-dark-indigo">Тёмная (Индиго)</Option>
                <Option value="theme-dark-slate">Тёмная (Слейт)</Option>
                <Option value="theme-light-indigo">Светлая (Индиго)</Option>
              </Select>
            </Form.Item>
          </Col>
        </Row>

        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Компактный режим" name="compactMode" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
          
          <Col xs={24} md={12}>
            <Form.Item label="Анимации" name="showAnimations" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
        </Row>

        <Divider />

        <Title level={4}>Настройки чата</Title>
        
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Размер шрифта" name="fontSize">
              <Select>
                <Option value="small">Маленький</Option>
                <Option value="medium">Средний</Option>
                <Option value="large">Большой</Option>
              </Select>
            </Form.Item>
          </Col>
          
          <Col xs={24} md={12}>
            <Form.Item label="Автосохранение" name="autoSave" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
        </Row>

        <Form.Item>
          <Button type="primary" htmlType="submit" size="middle">
            Сохранить настройки
          </Button>
        </Form.Item>
      </Form>
    </div>
  );
};

// Остальные вкладки уже используют Ant Design стили; добавим только отступы контейнера
const SecurityTab: React.FC = () => {
  const [form] = Form.useForm();
  const [showPassword, setShowPassword] = useState(false);
  const onFinish = (values: any) => { console.log('Настройки безопасности сохранены:', values); };
  return (
    <div style={{ padding: 'var(--sp-spacing-xs)' }}>
      <Title level={3} style={{ marginTop: 0 }}>Безопасность аккаунта</Title>
      <Alert
        message="Рекомендации по безопасности"
        description="Используйте сложные пароли, включите двухфакторную аутентификацию и регулярно проверяйте активность аккаунта."
        type="info"
        showIcon
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      />
      <Form form={form} layout="vertical" onFinish={onFinish}>
        <Title level={4}>Смена пароля</Title>
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Текущий пароль" name="currentPassword" rules={[{ required: true, message: 'Введите текущий пароль' }]}>
              <Input.Password prefix={<LockOutlined />} placeholder="Введите текущий пароль" />
            </Form.Item>
          </Col>
        </Row>
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Новый пароль" name="newPassword" rules={[{ required: true, message: 'Введите новый пароль' }, { min: 8, message: 'Пароль должен содержать минимум 8 символов' }]}>
              <Input.Password prefix={<LockOutlined />} placeholder="Введите новый пароль" />
            </Form.Item>
          </Col>
          <Col xs={24} md={12}>
            <Form.Item label="Подтверждение пароля" name="confirmPassword" rules={[({ getFieldValue }) => ({ validator(_, value) { if (!value || getFieldValue('newPassword') === value) return Promise.resolve(); return Promise.reject(new Error('Пароли не совпадают')); } })]}> 
              <Input.Password prefix={<LockOutlined />} placeholder="Подтвердите новый пароль" />
            </Form.Item>
          </Col>
        </Row>
        <Divider />
        <Title level={4}>Дополнительная безопасность</Title>
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Двухфакторная аутентификация" name="twoFactorAuth" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
          <Col xs={24} md={12}>
            <Form.Item label="Уведомления о входе" name="loginNotifications" valuePropName="checked">
              <Switch />
            </Form.Item>
          </Col>
        </Row>
        <Row gutter={[16, 12]}>
          <Col xs={24} md={12}>
            <Form.Item label="Автоматический выход" name="autoLogout">
              <Select>
                <Option value="never">Никогда</Option>
                <Option value="1h">Через 1 час</Option>
                <Option value="4h">Через 4 часа</Option>
                <Option value="24h">Через 24 часа</Option>
              </Select>
            </Form.Item>
          </Col>
        </Row>
        <Form.Item>
          <Button type="primary" htmlType="submit" size="middle" danger>
            Сохранить настройки безопасности
          </Button>
        </Form.Item>
      </Form>
    </div>
  );
};

