// Вкладка Debug
interface DebugTabProps {
  openDebugTool: () => void;
}

const DebugTab: React.FC<DebugTabProps> = ({ openDebugTool }) => {
  const [apiStatus, setApiStatus] = useState<string>('Не проверено');
  const [apiStatusType, setApiStatusType] = useState<'info' | 'success' | 'error' | 'warning'>('info');

  const testAPI = async () => {
    try {
      setApiStatus('Проверка...');
      setApiStatusType('info');
      
      const hdrs: Record<string,string> = {};
      try {
        const id = sessionStorage.getItem('tg_id');
        if (id) hdrs['X-Telegram-User-ID'] = String(id);
      } catch {}
      const response = await fetch('/api/health', { headers: hdrs });
      if (response.ok) {
        const data = await response.json();
        setApiStatus(`✅ API работает: ${data.status} v${data.version}`);
        setApiStatusType('success');
      } else {
        setApiStatus(`❌ Ошибка API: ${response.status}`);
        setApiStatusType('error');
      }
    } catch (error) {
      setApiStatus(`💥 Ошибка соединения: ${error instanceof Error ? error.message : 'Неизвестная ошибка'}`);
      setApiStatusType('error');
    }
  };

  const checkTelegramWebApp = () => {
    const checks = [
      { name: 'Window defined', value: typeof window !== 'undefined' },
      { name: 'Telegram exists', value: !!(window as any).Telegram },
      { name: 'WebApp exists', value: !!(window as any).Telegram?.WebApp },
      { name: 'initDataUnsafe exists', value: !!(window as any).Telegram?.WebApp?.initDataUnsafe },
      { name: 'User exists', value: !!(window as any).Telegram?.WebApp?.initDataUnsafe?.user }
    ];

    return checks;
  };

  const telegramChecks = checkTelegramWebApp();
  const telegramOK = telegramChecks.every(check => check.value);

  const sessionData = {
    tg_id: sessionStorage.getItem('tg_id'),
    telegram_user: sessionStorage.getItem('telegram_user')
  };

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)' }}>
      <Title level={3} style={{ marginTop: 0 }}>🔧 Debug инструменты</Title>
      <Paragraph>
        Инструменты для диагностики проблем с авторизацией и API подключением
      </Paragraph>

      {/* Быстрая диагностика */}
      <Card title="🚀 Быстрая диагностика" className="mb-4">
        <Row gutter={16}>
          <Col span={12}>
            <Space direction="vertical" style={{ width: '100%' }}>
              <div>
                <Text strong>API подключение:</Text>
                <div>
                  <Alert
                    message={apiStatus}
                    type={apiStatusType}
                    style={{ marginTop: 'var(--sp-spacing-sm)', marginBottom: 'var(--sp-spacing-sm)' }}
                  />
                  <Button onClick={testAPI} size="small">
                    Проверить API
                  </Button>
                </div>
              </div>
            </Space>
          </Col>
          <Col span={12}>
            <div>
              <Text strong>Telegram WebApp:</Text>
              <div style={{ marginTop: 'var(--sp-spacing-sm)' }}>
                <Alert
                  message={telegramOK ? '✅ Все проверки пройдены' : '❌ Есть проблемы'}
                  type={telegramOK ? 'success' : 'warning'}
                  style={{ marginBottom: 'var(--sp-spacing-sm)' }}
                />
                {telegramChecks.map((check, index) => (
                  <Tag 
                    key={index} 
                    color={check.value ? 'green' : 'red'}
                    style={{ marginBottom: 4 }}
                  >
                    {check.value ? '✅' : '❌'} {check.name}
                  </Tag>
                ))}
              </div>
            </div>
          </Col>
        </Row>
      </Card>

      {/* SessionStorage данные */}
      <Card title="💾 SessionStorage" className="mb-4">
        <Row gutter={16}>
          <Col span={12}>
            <div>
              <Text strong>tg_id:</Text>
              <div style={{ marginTop: 'var(--sp-spacing-xs)' }}>
                <Tag color={sessionData.tg_id ? 'green' : 'red'}>
                  {sessionData.tg_id || 'Не найден'}
                </Tag>
              </div>
            </div>
          </Col>
          <Col span={12}>
            <div>
              <Text strong>telegram_user:</Text>
              <div style={{ marginTop: 'var(--sp-spacing-xs)' }}>
                <Tag color={sessionData.telegram_user ? 'green' : 'red'}>
                  {sessionData.telegram_user ? 'Найден' : 'Не найден'}
                </Tag>
              </div>
            </div>
          </Col>
        </Row>
        
        {sessionData.telegram_user && (
          <div style={{ marginTop: 'var(--sp-spacing-md)' }}>
            <Text strong>Данные пользователя:</Text>
            <Input.TextArea 
              value={sessionData.telegram_user} 
              readOnly 
              rows={3}
              style={{ marginTop: 'var(--sp-spacing-sm)' }}
            />
          </div>
        )}
      </Card>

      {/* Инструменты */}
      <Card title="🛠️ Инструменты диагностики">
        <Space direction="vertical" style={{ width: '100%' }}>
          <Button 
            type="primary" 
            icon={<SecurityScanOutlined />}
            onClick={openDebugTool}
            size="large"
          >
            Открыть полный Debug инструмент
          </Button>
          
          <Button 
            onClick={() => {
              try {
                const tg = sessionStorage.getItem('tg_id');
                const rolesCache = sessionStorage.getItem('sp_roles_cache');
                const sticky = sessionStorage.getItem('sp_roles_sticky');
                sessionStorage.clear();
                if (tg) sessionStorage.setItem('tg_id', tg);
                if (rolesCache) sessionStorage.setItem('sp_roles_cache', rolesCache);
                if (sticky) sessionStorage.setItem('sp_roles_sticky', sticky);
              } catch {}
              window.location.reload();
            }}
            danger
          >
            Очистить SessionStorage и перезагрузить
          </Button>

          {/* Удалено: симуляция тестового пользователя */}

          <Button 
            onClick={() => {
              // Экспорт полной диагностики
              const diagnostics = {
                timestamp: new Date().toISOString(),
                userAgent: navigator.userAgent,
                url: window.location.href,
                apiStatus,
                telegramOK,
                telegramChecks,
                sessionData,
                systemInfo: {
                  platform: navigator.platform,
                  language: navigator.language,
                  screenSize: `${screen.width}x${screen.height}`,
                  windowSize: `${window.innerWidth}x${window.innerHeight}`
                }
              };
              
              const blob = new Blob([JSON.stringify(diagnostics, null, 2)], { 
                type: 'application/json' 
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `soulpulse-diagnostics-${Date.now()}.json`;
              a.click();
              URL.revokeObjectURL(url);
            }}
            type="default"
          >
            📥 Экспорт полной диагностики
          </Button>
        </Space>
      </Card>
    </div>
  );
};

export default Settings;
