import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Avatar, 
  Typography, 
  Space, 
  Tag, 
  Row, 
  Col, 
  Statistic, 
  Progress,
  Button,
  Divider,
  Input,
  Select,
  DatePicker,
  Switch,
  message,
  Tooltip,
  Badge
} from 'antd';
import { 
  UserOutlined, 
  CalendarOutlined, 
  EnvironmentOutlined, 
  PhoneOutlined,
  MailOutlined,
  CrownOutlined,
  TrophyOutlined,
  FireOutlined,
  HeartOutlined,
  MessageOutlined,
  ClockCircleOutlined,
  SettingOutlined,
  RobotOutlined,
  FileTextOutlined,
  EditOutlined,
  SaveOutlined,
  CloseOutlined,
  LockOutlined,
  UnlockOutlined,
  ReloadOutlined,
  ClearOutlined,
  DeleteOutlined,
  ExclamationCircleOutlined,
  ContactsOutlined,
  SyncOutlined
} from '@ant-design/icons';
import WebApp from '@twa-dev/sdk';
import { api, apiRequest, buildAuthHeaders } from '../api';
import { usePermissions } from '../hooks/usePermissions';

const { Title, Text, Paragraph } = Typography;
const { TextArea } = Input;

// Типы данных
interface TelegramUserData {
  id: number;
  first_name: string;
  last_name?: string;
  username?: string;
  language_code?: string;
  is_premium?: boolean;
  photo_url?: string;
}

interface UserProfileData {
  telegram_id: number;
  telegram_first_name: string;
  telegram_last_name: string;
  telegram_username: string;
  telegram_language: string;
  telegram_is_premium: boolean;
  telegram_photo_url?: string;
  display_name: string;
  bio: string;
  birth_date: string;
  gender?: string;
  location: string;
  timezone: string;
  phone_number: string;
  email: string;
  favorite_topics: string[];
  
  // Новые поля персонификации
  nickname?: string;
  age?: number;
  profession?: string;
  interests?: string[];
  personality_traits?: string[];
  relationship_status?: string;
  family_info?: Record<string, string>;
  goals?: string[];
  preferences?: Record<string, string>;
  important_dates?: Record<string, string>;
  
  // Состояние знакомства
  is_familiar?: boolean;
  first_meeting_date?: string;
  last_interaction_date?: string;
  familiarity_level?: 'stranger' | 'acquaintance' | 'friend' | 'close_friend';
  
  // Статистика
  registration_date: string;
  last_seen: string;
  total_messages: number;
  ai_interactions: number;
  prompt_usage: Record<string, number>;
  subscription_level: 'basic' | 'premium' | 'corporate';
}

interface UserProfileProps {
  prompts: any[]; // Передаем промпты для статистики
}

const UserProfile: React.FC<UserProfileProps> = ({ prompts }) => {
  const [profileData, setProfileData] = useState<UserProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [editForm, setEditForm] = useState<Partial<UserProfileData>>({});
  const [saving, setSaving] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const { state: permState } = usePermissions();

	// Голос: быстрый переключатель
	type VoiceItem = { id: string; provider?: string; model?: string; display_name?: string };
	const [availableVoices, setAvailableVoices] = useState<VoiceItem[]>([]);
	const [voicePersonaKey, setVoicePersonaKey] = useState<string>('FR_Ranevskaya_Persona_v1_4');
	const [voiceId, setVoiceId] = useState<string>('');
	const [voiceLoading, setVoiceLoading] = useState<boolean>(false);

  // Получаем данные из Telegram WebApp или из sessionStorage (без тестовых хардкодов)
  const userData = (() => {
    const tg = WebApp.initDataUnsafe?.user;
    if (tg && tg.id) return tg;
    try {
      const stored = sessionStorage.getItem('telegram_user');
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed && parsed.id) return parsed;
      }
    } catch {}
    return { id: 0, first_name: '', last_name: '', username: '', language_code: '', is_premium: false, photo_url: undefined } as any;
  })();

  // Загружаем профиль из БД
  useEffect(() => {
    const loadProfile = async () => {
      setLoading(true);
      try {
        // Сначала создаем базовый профиль с данными из Telegram
        console.log('🔧 Данные пользователя для аватара:', userData);
        const baseProfile: UserProfileData = {
          telegram_id: userData.id,
          telegram_first_name: userData.first_name || '',
          telegram_last_name: userData.last_name || '',
          telegram_username: userData.username || '',
          telegram_language: (userData.language_code || '').toUpperCase(),
          telegram_is_premium: userData.is_premium || false,
          telegram_photo_url: userData.photo_url,
          display_name: userData.first_name || userData.username || '',
          bio: userData.username ? `@${userData.username}` : '',
          birth_date: '',
          gender: undefined,
          location: '',
          timezone: 'Europe/Moscow',
          phone_number: '',
          email: '',
          favorite_topics: [],
          registration_date: new Date().toISOString(),
          last_seen: new Date().toISOString(),
          total_messages: 0,
          ai_interactions: 0,
          prompt_usage: {},
          subscription_level: 'basic'
        };

        // Пытаемся загрузить профиль из БД (передаем X-Telegram-User-ID)
        try {
          // В проде запрещаем dev-эндпоинт: используем защищённый профиль
          const data = await apiRequest('/miniapp/profile', 'GET');
          console.log('Профиль загружен из БД:', data);
          
          if (data.profile) {
            // Если сервер прислал photo_url / first_name / last_name, используем их
            // Объединяем данные из БД с базовыми данными Telegram
            const mergedProfile = {
              // Сначала Telegram, затем БД — Telegram имеет приоритет
              ...data.profile,
              ...baseProfile,
              telegram_id: baseProfile.telegram_id,
              telegram_first_name: baseProfile.telegram_first_name || data.profile.telegram_first_name,
              telegram_last_name: baseProfile.telegram_last_name || data.profile.telegram_last_name,
              telegram_username: baseProfile.telegram_username || data.profile.telegram_username,
              telegram_language: baseProfile.telegram_language || data.profile.telegram_language,
              telegram_is_premium: typeof baseProfile.telegram_is_premium === 'boolean' ? baseProfile.telegram_is_premium : data.profile.telegram_is_premium,
              telegram_photo_url: baseProfile.telegram_photo_url || data.profile.telegram_photo_url,
              display_name: baseProfile.display_name || data.profile.display_name,
              bio: baseProfile.bio || data.profile.bio,
            } as UserProfileData;
            console.log('👤 Итоговый профиль:', mergedProfile);
            console.log('🖼️ Фото URL:', mergedProfile.telegram_photo_url);
            console.log('📛 Имя для аватара:', mergedProfile.telegram_first_name, mergedProfile.telegram_last_name);
            setProfileData(mergedProfile);
            setEditForm(mergedProfile);
          } else {
            // Если профиля нет в БД, используем базовый
            console.log('👤 Используем базовый профиль:', baseProfile);
            setProfileData(baseProfile);
            setEditForm(baseProfile);
          }
        } catch (apiError) {
          console.warn('Ошибка API, используем базовый профиль:', apiError);
          setProfileData(baseProfile);
          setEditForm(baseProfile);
        }
      } catch (error) {
        console.error('Критическая ошибка при создании профиля:', error);
        // В случае критической ошибки создаем минимальный профиль
        const minimalProfile: UserProfileData = {
          telegram_id: userData.id || 0,
          telegram_first_name: userData.first_name || '',
          telegram_last_name: userData.last_name || '',
          telegram_username: userData.username || '',
          telegram_language: (userData.language_code || '').toUpperCase(),
          telegram_is_premium: !!userData.is_premium,
          telegram_photo_url: userData.photo_url,
          display_name: userData.first_name || userData.username || '',
          bio: userData.username ? `@${userData.username}` : '',
          birth_date: '',
          gender: undefined,
          location: '',
          timezone: 'Europe/Moscow',
          phone_number: '',
          email: '',
          favorite_topics: [],
          registration_date: new Date().toISOString(),
          last_seen: new Date().toISOString(),
          total_messages: 0,
          ai_interactions: 0,
          prompt_usage: {},
          subscription_level: 'basic'
        };
        setProfileData(minimalProfile);
        setEditForm(minimalProfile);
      } finally {
        setLoading(false);
      }
    };

    loadProfile();
  }, [userData.id, userData.username, userData.first_name, userData.last_name]);

	// Загрузка доступных голосов для быстрого переключателя
	useEffect(() => {
		const loadVoices = async () => {
			try {
				setVoiceLoading(true);
				const res = await apiRequest('/voice/voices', 'GET');
				const items: any[] = Array.isArray(res?.items) ? res.items : (Array.isArray(res) ? res : []);
				const mapped: VoiceItem[] = items.map((it: any) => ({
					id: String(it.id ?? it.model ?? it.display_name ?? ''),
					provider: String(it.provider ?? ''),
					model: it.model,
					display_name: it.display_name ?? it.id
				})).filter(v => !!v.id);
				setAvailableVoices(mapped);
				if (!voiceId && mapped.length > 0) setVoiceId(mapped[0].id);
			} catch {
				// молча, чтобы не мешать профилю
			} finally {
				setVoiceLoading(false);
			}
		};
		void loadVoices();
	}, []);

	const doApplyVoice = async () => {
		if (!voicePersonaKey || !voiceId) { message.warning('Выберите персону и голос'); return; }
		try {
			setVoiceLoading(true);
			const body: any = { persona_key: voicePersonaKey, voice_id: voiceId };
			await apiRequest('/voice/set_voice', 'POST', body);
			message.success('Голос применён');
		} catch (e) {
			message.error('Не удалось применить голос');
		} finally {
			setVoiceLoading(false);
		}
	};

  const handleEdit = () => {
    setEditing(true);
    setEditForm(profileData || {});
  };

  const handleCancel = () => {
    setEditing(false);
    setEditForm(profileData || {});
  };

  // Функция для сохранения профиля в localStorage
  const saveProfileToStorage = (profile: UserProfileData) => {
    try {
      const profileForStorage = {
        display_name: profile.display_name,
        bio: profile.bio,
        location: profile.location,
        favorite_topics: profile.favorite_topics,
        birth_date: profile.birth_date,
        gender: profile.gender
      };
      
      localStorage.setItem('userProfile', JSON.stringify(profileForStorage));
      console.log('Профиль сохранен в localStorage:', profileForStorage);
    } catch (error) {
      console.error('Ошибка при сохранении профиля в localStorage:', error);
    }
  };

  // Обновляем функцию handleSave для сохранения в localStorage
  const handleSave = async () => {
    try {
      setSaving(true);
      
      // Создаем полный профиль с обязательными полями
      const fullProfile: UserProfileData = {
        ...profileData!, // Используем существующий профиль как базу
        ...editForm, // Обновляем только измененные поля
      };
      
      // Сохраняем в localStorage
      saveProfileToStorage(fullProfile);
      
      // Обновляем состояние
      setProfileData(fullProfile);
      setEditing(false);
      
      message.success('Профиль успешно обновлен!');
    } catch (error) {
      console.error('Ошибка при сохранении профиля:', error);
      message.error('Ошибка при сохранении профиля');
    } finally {
      setSaving(false);
    }
  };

  // Функция для обновления профиля из Telegram
  const handleUpdateProfile = async () => {
    try {
      setActionLoading('update');
      
      const tgId = sessionStorage.getItem('tg_id');
      if (!tgId) {
        message.error('Ошибка: не найден Telegram ID');
        return;
      }

      // Получаем все доступные данные из Telegram WebApp
      const telegramUser = WebApp.initDataUnsafe?.user;
      if (!telegramUser) {
        message.error('Ошибка: не удалось получить данные из Telegram WebApp');
        return;
      }

      console.log('📊 Отправляем данные Telegram:', telegramUser);

      // Подготавливаем данные для отправки
      const requestData = {
        telegram_user_data: {
          id: telegramUser.id,
          first_name: telegramUser.first_name || null,
          last_name: telegramUser.last_name || null,
          username: telegramUser.username || null,
          language_code: telegramUser.language_code || null,
          is_premium: telegramUser.is_premium || false,
          allows_write_to_pm: telegramUser.allows_write_to_pm || false,
          photo_url: telegramUser.photo_url || null,
          phone_number: null // Пока не поддерживается, нужна отдельная реализация
        }
      };

      const response = await fetch('/api/profile/auto-fill-from-telegram', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId
        },
        body: JSON.stringify(requestData)
      });

      if (response.ok) {
        const result = await response.json();
        const updatedFields = result.updated_fields || [];
        
        if (updatedFields.length > 0) {
          message.success(`Профиль обновлен! Обновлено полей: ${updatedFields.join(', ')}`);
        } else {
          message.info('Профиль уже содержит актуальные данные из Telegram');
        }
        
        console.log('✅ Результат обновления:', result);
        
        // Перезагружаем профиль
        setTimeout(() => {
          window.location.reload();
        }, 1500);
      } else {
        const errorData = await response.json();
        message.error(`Ошибка обновления профиля: ${errorData.detail || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка при обновлении профиля:', error);
      message.error('Ошибка при обновлении профиля');
    } finally {
      setActionLoading(null);
    }
  };

  // Функция для очистки кеша
  const handleClearCache = async () => {
    try {
      setActionLoading('cache');
      
      const tgId = sessionStorage.getItem('tg_id');
      if (!tgId) {
        message.error('Ошибка: не найден Telegram ID');
        return;
      }

      const response = await fetch('/api/cache/clear', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId
        }
      });

      if (response.ok) {
        // Очищаем локальный кеш БЕЗ tg_id/roles cache
        try {
          const tg = sessionStorage.getItem('tg_id');
          const rolesCache = sessionStorage.getItem('sp_roles_cache');
          const sticky = sessionStorage.getItem('sp_roles_sticky');
          sessionStorage.clear();
          if (tg) sessionStorage.setItem('tg_id', tg);
          if (rolesCache) sessionStorage.setItem('sp_roles_cache', rolesCache);
          if (sticky) sessionStorage.setItem('sp_roles_sticky', sticky);
        } catch {}
        try { localStorage.removeItem('token'); } catch {}
        
        message.success('Кеш успешно очищен! Страница будет перезагружена.');
        
        // Перезагружаем страницу через 1 секунду
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      } else {
        const errorData = await response.json();
        message.error(`Ошибка очистки кеша: ${errorData.detail || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка при очистке кеша:', error);
      message.error('Ошибка при очистке кеша');
    } finally {
      setActionLoading(null);
    }
  };

  // Функция для запроса номера телефона через Telegram Bot
  const handleRequestPhoneNumber = async () => {
    try {
      setActionLoading('phone');
      
      // Показываем инструкцию пользователю
      const confirmed = window.confirm(
        'Для получения номера телефона:\n\n' +
        '1. Откройте чат с ботом @SoulPulsePhoneBot\n' +
        '2. Нажмите кнопку "📱 Поделиться номером телефона"\n' +
        '3. Вернитесь в мини-приложение и нажмите "Обновить профиль"\n\n' +
        'Хотите открыть чат с ботом?'
      );

      if (confirmed) {
        // Открываем чат с ботом
        const botUsername = 'soulpulse_mini_bot';
        const botUrl = `https://t.me/${botUsername}`;
        
        if (WebApp.openTelegramLink) {
          WebApp.openTelegramLink(botUrl);
        } else {
          window.open(botUrl, '_blank');
        }
        
        message.info('Откройте чат с ботом и поделитесь номером телефона');
      }
    } catch (error) {
      console.error('Ошибка при запросе номера телефона:', error);
      message.error('Ошибка при запросе номера телефона');
    } finally {
      setActionLoading(null);
    }
  };

  // Функция для удаления аккаунта
  const handleDeleteAccount = async () => {
    try {
      setActionLoading('delete');
      
      const tgId = sessionStorage.getItem('tg_id');
      if (!tgId) {
        message.error('Ошибка: не найден Telegram ID');
        return;
      }

      // Показываем подтверждение
      const confirmed = window.confirm(
        'Вы уверены, что хотите удалить свой аккаунт?\n\n' +
        'Это действие необратимо и удалит:\n' +
        '• Все ваши сообщения и чаты\n' +
        '• Настройки и предпочтения\n' +
        '• Профиль и персональные данные\n\n' +
        'Нажмите OK для подтверждения удаления.'
      );

      if (!confirmed) {
        setActionLoading(null);
        return;
      }

      const response = await fetch('/api/account/delete', {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          'X-Telegram-User-ID': tgId
        }
      });

      if (response.ok) {
        // Очищаем все данные, но не теряем tg_id/roles
        try {
          const tg = sessionStorage.getItem('tg_id');
          const rolesCache = sessionStorage.getItem('sp_roles_cache');
          const sticky = sessionStorage.getItem('sp_roles_sticky');
          sessionStorage.clear();
          if (tg) sessionStorage.setItem('tg_id', tg);
          if (rolesCache) sessionStorage.setItem('sp_roles_cache', rolesCache);
          if (sticky) sessionStorage.setItem('sp_roles_sticky', sticky);
        } catch {}
        try { localStorage.removeItem('token'); } catch {}
        
        message.success('Аккаунт успешно удален. До свидания!');
        
        // Перенаправляем на главную страницу через 2 секунды
        setTimeout(() => {
          window.location.href = '/';
        }, 2000);
      } else {
        const errorData = await response.json();
        message.error(`Ошибка удаления аккаунта: ${errorData.detail || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка при удалении аккаунта:', error);
      message.error('Ошибка при удалении аккаунта');
    } finally {
      setActionLoading(null);
    }
  };

  const getAge = (birthDate: string) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    
    return age;
  };

  const getGenderIcon = (gender: string) => {
    switch (gender) {
      case 'male': return '👨';
      case 'female': return '👩';
      default: return '👤';
    }
  };

  const getGenderLabel = (gender: string) => {
    switch (gender) {
      case 'male': return 'Мужской';
      case 'female': return 'Женский';
      default: return 'Другой';
    }
  };

  const getSubscriptionColor = (level: string) => {
    switch (level) {
      case 'basic': return 'blue';
      case 'premium': return 'purple';
      case 'corporate': return 'gold';
      default: return 'default';
    }
  };

  const getSubscriptionIcon = (level: string) => {
    switch (level) {
      case 'basic': return '🔵';
      case 'premium': return '🟣';
      case 'corporate': return '🟡';
      default: return '⚪';
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        <Text style={{ marginLeft: 'var(--sp-spacing-md)' }}>Загрузка профиля...</Text>
      </div>
    );
  }

  if (!profileData) {
    return (
      <Card>
        <div className="text-center" style={{ padding: 'var(--sp-spacing-2xl) 0' }}>
          <UserOutlined style={{ fontSize: 'var(--sp-font-size-3xl)', color: 'var(--sp-text-tertiary)', marginBottom: 'var(--sp-spacing-md)' }} />
          <Text type="secondary">Не удалось загрузить профиль пользователя</Text>
        </div>
      </Card>
    );
  }

  return (
    <div className="container profile-page" style={{ width: '100%', maxWidth: '100%', boxSizing: 'border-box' }}>
      {/* Заголовок */}
      <div className="soulpulse-header">
        <Title className="soulpulse-title">
          <UserOutlined style={{ marginRight: 'var(--sp-spacing-md)' }} />
          Профиль пользователя
        </Title>
        <Text className="soulpulse-subtitle">
          Управление персональными данными и настройками
        </Text>
      </div>

      <Row gutter={[24, 24]}>
        {/* Основная информация */}
        <Col xs={24} lg={16}>
          <Card 
            title={<div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><span>Основная информация</span></div>}
            className="mb-4"
          >
            <Row gutter={[24, 16]}>
              <Col xs={24} md={8}>
                <div className="text-center">
                  <Avatar 
                    size={80} 
                    src={
                      profileData.telegram_photo_url || 
                      '/android-chrome-192x192.png'
                    }
                    icon={<UserOutlined />}
                    style={{ marginBottom: 'var(--sp-spacing-lg)' }}
                    onError={() => {
                      // Ошибка загрузки аватара — показываем иконку
                      return true;
                    }}
                  />
                  <div>
                    <Title level={5} style={{ margin: 'var(--sp-spacing-sm) 0' }}>
                      {profileData.display_name || profileData.telegram_first_name}
                    </Title>
                    {profileData.telegram_username && (
                      <Text type="secondary">@{profileData.telegram_username}</Text>
                    )}
                  </div>
                </div>
              </Col>
              
              <Col xs={24} md={16}>
                <Space direction="vertical" size="large" style={{ width: '100%' }}>
                  {/* Telegram данные (не редактируемые) */}
                  <div>
                    <Text strong>
                      <LockOutlined style={{ marginRight: 'var(--sp-spacing-sm)', color: 'var(--sp-text-tertiary)' }} />
                      ID пользователя:
                    </Text>
                    <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.telegram_id}</Text>
                    <Tag color="blue" icon={<LockOutlined />}>
                      Telegram
                    </Tag>
                  </div>
                  
                  <div>
                    <Text strong>
                      <LockOutlined style={{ marginRight: 'var(--sp-spacing-sm)', color: 'var(--sp-text-tertiary)' }} />
                      Имя:
                    </Text>
                    <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.telegram_first_name}</Text>
                    {profileData.telegram_last_name && (
                      <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.telegram_last_name}</Text>
                    )}
                    <Tag color="blue" icon={<LockOutlined />}>
                      Telegram
                    </Tag>
                  </div>

                  {/* Редактируемые поля */}
                  <div>
                    <Text strong>Отображаемое имя:</Text>
                    {editing ? (
                      <Input
                        value={editForm.display_name || ''}
                        onChange={(e) => setEditForm({...editForm, display_name: e.target.value})}
                        placeholder="Введите отображаемое имя"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    ) : (
                      <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                        {profileData.display_name || profileData.telegram_first_name}
                      </Text>
                    )}
                  </div>

                  <div>
                    <Text strong>О себе:</Text>
                    {editing ? (
                      <TextArea
                        value={editForm.bio || ''}
                        onChange={(e) => setEditForm({...editForm, bio: e.target.value})}
                        placeholder="Расскажите о себе"
                        rows={3}
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '100%' }}
                      />
                    ) : (
                      <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                        {profileData.bio || 'Не указано'}
                      </Text>
                    )}
                  </div>
                  
                  {editing ? (
                    <div>
                      <Text strong>Дата рождения:</Text>
                      <DatePicker
                        value={editForm.birth_date ? new Date(editForm.birth_date) : null}
                        onChange={(date) => setEditForm({
                          ...editForm, 
                          birth_date: date ? date.toISOString() : undefined
                        })}
                        style={{ marginLeft: 'var(--sp-spacing-sm)' }}
                      />
                    </div>
                  ) : (
                    profileData.birth_date && (
                      <div>
                        <Text strong>Дата рождения:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          {new Date(profileData.birth_date).toLocaleDateString('ru-RU')} 
                          ({getAge(profileData.birth_date)} лет)
                        </Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Пол:</Text>
                      <Select
                        value={editForm.gender}
                        onChange={(value) => setEditForm({...editForm, gender: value})}
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '150px' }}
                        placeholder="Выберите пол"
                      >
                        <Select.Option value="male">👨 Мужской</Select.Option>
                        <Select.Option value="female">👩 Женский</Select.Option>
                        <Select.Option value="other">👤 Другой</Select.Option>
                      </Select>
                    </div>
                  ) : (
                    profileData.gender && (
                      <div>
                        <Text strong>Пол:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          {getGenderIcon(profileData.gender)} {getGenderLabel(profileData.gender)}
                        </Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Местоположение:</Text>
                      <Input
                        value={editForm.location || ''}
                        onChange={(e) => setEditForm({...editForm, location: e.target.value})}
                        placeholder="Введите местоположение"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    </div>
                  ) : (
                    profileData.location && (
                      <div>
                        <Text strong>Местоположение:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          <EnvironmentOutlined style={{ marginRight: 'var(--sp-spacing-xs)' }} />
                          {profileData.location}
                        </Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Телефон:</Text>
                      <Input
                        value={editForm.phone_number || ''}
                        onChange={(e) => setEditForm({...editForm, phone_number: e.target.value})}
                        placeholder="Введите номер телефона"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    </div>
                  ) : (
                    profileData.phone_number && (
                      <div>
                        <Text strong>Телефон:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          <PhoneOutlined style={{ marginRight: 'var(--sp-spacing-xs)' }} />
                          {profileData.phone_number}
                        </Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Email:</Text>
                      <Input
                        value={editForm.email || ''}
                        onChange={(e) => setEditForm({...editForm, email: e.target.value})}
                        placeholder="Введите email"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    </div>
                  ) : (
                    profileData.email && (
                      <div>
                        <Text strong>Email:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          <MailOutlined style={{ marginRight: 'var(--sp-spacing-xs)' }} />
                          {profileData.email}
                        </Text>
                      </div>
                    )
                  )}

                  {/* Новые поля персонификации */}
                  {editing ? (
                    <div>
                      <Text strong>Прозвище/Как обращаться:</Text>
                      <Input
                        value={editForm.nickname || ''}
                        onChange={(e) => setEditForm({...editForm, nickname: e.target.value})}
                        placeholder="Как к вам обращаться?"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    </div>
                  ) : (
                    profileData.nickname && (
                      <div>
                        <Text strong>Прозвище:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.nickname}</Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Возраст:</Text>
                      <Input
                        type="number"
                        value={editForm.age || ''}
                        onChange={(e) => setEditForm({...editForm, age: parseInt(e.target.value) || undefined})}
                        placeholder="Введите возраст"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '100px' }}
                      />
                    </div>
                  ) : (
                    profileData.age && (
                      <div>
                        <Text strong>Возраст:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.age} лет</Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Профессия:</Text>
                      <Input
                        value={editForm.profession || ''}
                        onChange={(e) => setEditForm({...editForm, profession: e.target.value})}
                        placeholder="Ваша профессия"
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                      />
                    </div>
                  ) : (
                    profileData.profession && (
                      <div>
                        <Text strong>Профессия:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>{profileData.profession}</Text>
                      </div>
                    )
                  )}

                  {editing ? (
                    <div>
                      <Text strong>Семейное положение:</Text>
                      <Select
                        value={editForm.relationship_status}
                        onChange={(value) => setEditForm({...editForm, relationship_status: value})}
                        style={{ marginLeft: 'var(--sp-spacing-sm)', width: '200px' }}
                        placeholder="Выберите статус"
                        allowClear
                      >
                        <Select.Option value="single">Холост/Не замужем</Select.Option>
                        <Select.Option value="married">Женат/Замужем</Select.Option>
                        <Select.Option value="divorced">Разведен(а)</Select.Option>
                        <Select.Option value="widowed">Вдовец/Вдова</Select.Option>
                        <Select.Option value="relationship">В отношениях</Select.Option>
                      </Select>
                    </div>
                  ) : (
                    profileData.relationship_status && (
                      <div>
                        <Text strong>Семейное положение:</Text>
                        <Text style={{ marginLeft: 'var(--sp-spacing-sm)' }}>
                          {profileData.relationship_status === 'single' ? 'Холост/Не замужем' :
                           profileData.relationship_status === 'married' ? 'Женат/Замужем' :
                           profileData.relationship_status === 'divorced' ? 'Разведен(а)' :
                           profileData.relationship_status === 'widowed' ? 'Вдовец/Вдова' :
                           profileData.relationship_status === 'relationship' ? 'В отношениях' :
                           profileData.relationship_status}
                        </Text>
                      </div>
                    )
                  )}

                  <div>
                    <Text strong>Язык:</Text>
                    <Tag color="blue" icon={<LockOutlined />}>
                      {profileData.telegram_language?.toUpperCase() || 'RU'}
                    </Tag>
                    <Tag color="blue" icon={<LockOutlined />}>
                      Telegram
                    </Tag>
                  </div>
                </Space>
              </Col>
            </Row>

            {/* Нижняя панель действий под блоком информации (компактные кнопки в сетке 2x) */}
            <Divider style={{ margin: '12px 0' }} />
            <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
              <Tooltip title="Обновить из Telegram">
                <Button 
                  shape="circle"
                  icon={<ReloadOutlined />}
                  loading={actionLoading === 'update'}
                  onClick={handleUpdateProfile}
                  size="small"
                  type="primary"
                />
              </Tooltip>
              <Tooltip title="Синхронизация">
              <Button 
                shape="circle"
                icon={<SyncOutlined />}
                onClick={() => { try { (window as any).dispatchEvent(new Event('sp:auth')); } catch {}; try { window.location.hash = '#/webauth'; } catch { window.location.replace('/#\/webauth'); } }}
                size="small"
              />
              </Tooltip>
            </div>
          </Card>

          {/* Статистика активности */}
          <Card title="Статистика активности" className="mb-4">
            <Row gutter={[16, 16]}>
              <Col xs={12} md={6}>
                <Statistic
                  title="Всего сообщений"
                  value={profileData.total_messages}
                  prefix={<MessageOutlined />}
                  valueStyle={{ color: 'var(--primary-color)' }}
                />
              </Col>
              <Col xs={12} md={6}>
                <Statistic
                  title="AI взаимодействий"
                  value={profileData.ai_interactions}
                  prefix={<RobotOutlined />}
                  valueStyle={{ color: 'var(--secondary-color)' }}
                />
              </Col>
              <Col xs={12} md={6}>
                <Statistic
                  title="Дней в системе"
                  value={Math.floor((new Date().getTime() - new Date(profileData.registration_date).getTime()) / (1000 * 60 * 60 * 24))}
                  prefix={<CalendarOutlined />}
                  valueStyle={{ color: 'var(--accent-color)' }}
                />
              </Col>
              <Col xs={12} md={6}>
                <Statistic
                  title="Премиум статус"
                  value={profileData.telegram_is_premium ? 'Да' : 'Нет'}
                  prefix={profileData.telegram_is_premium ? <CrownOutlined /> : <UserOutlined />}
                  valueStyle={{ color: profileData.telegram_is_premium ? 'var(--warning-color)' : 'var(--text-muted)' }}
                />
              </Col>
            </Row>
          </Card>

          {/* Использование промптов */}
          {Object.keys(profileData.prompt_usage).length > 0 && (
            <Card title="Использование промптов" className="mb-4">
              <Space direction="vertical" style={{ width: '100%' }}>
                {Object.entries(profileData.prompt_usage).map(([prompt, count]) => (
                  <div key={prompt} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Text>{prompt}</Text>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                      <Progress 
                        percent={Math.round((count / profileData.ai_interactions) * 100)} 
                        size="small" 
                        style={{ width: '100px' }}
                      />
                      <Text type="secondary">{count}</Text>
                    </div>
                  </div>
                ))}
              </Space>
            </Card>
          )}

          {/* Любимые темы */}
          {profileData.favorite_topics && profileData.favorite_topics.length > 0 && (
            <Card title="Любимые темы" className="mb-4">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                {profileData.favorite_topics.map(topic => (
                  <Tag key={topic} color="purple" icon={<HeartOutlined />}>
                    {topic}
                  </Tag>
                ))}
              </div>
            </Card>
          )}

          {/* Интересы */}
          {profileData.interests && profileData.interests.length > 0 && (
            <Card title="Интересы" className="mb-4">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                {profileData.interests.map(interest => (
                  <Tag key={interest} color="blue">
                    {interest}
                  </Tag>
                ))}
              </div>
            </Card>
          )}

          {/* Черты характера */}
          {profileData.personality_traits && profileData.personality_traits.length > 0 && (
            <Card title="Черты характера" className="mb-4">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                {profileData.personality_traits.map(trait => (
                  <Tag key={trait} color="green">
                    {trait}
                  </Tag>
                ))}
              </div>
            </Card>
          )}

          {/* Цели */}
          {profileData.goals && profileData.goals.length > 0 && (
            <Card title="Цели" className="mb-4">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                {profileData.goals.map(goal => (
                  <Tag key={goal} color="orange">
                    {goal}
                  </Tag>
                ))}
              </div>
            </Card>
          )}

          {/* Важные даты */}
          {profileData.important_dates && Object.keys(profileData.important_dates).length > 0 && (
            <Card title="Важные даты" className="mb-4">
              <Space direction="vertical" style={{ width: '100%' }}>
                {Object.entries(profileData.important_dates).map(([event, date]) => (
                  <div key={event} style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Text strong>{event}:</Text>
                    <Text>{date}</Text>
                  </div>
                ))}
              </Space>
            </Card>
          )}

          {/* Семья */}
          {profileData.family_info && Object.keys(profileData.family_info).length > 0 && (
            <Card title="Семья" className="mb-4">
              <Space direction="vertical" style={{ width: '100%' }}>
                {Object.entries(profileData.family_info).map(([relation, name]) => (
                  <div key={relation} style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Text strong>{relation}:</Text>
                    <Text>{name}</Text>
                  </div>
                ))}
              </Space>
            </Card>
          )}
        </Col>

        {/* Боковая панель */}
        <Col xs={24} lg={8}>
          {/* Быстрый переключатель голоса */}
          <Card title="Голос ассистента" className="mb-4">
            <Space direction="vertical" style={{ width: '100%' }} size={8}>
              <div>
                <Text strong>Персона</Text>
                <Select
                  value={voicePersonaKey}
                  onChange={(v) => setVoicePersonaKey(v)}
                  style={{ width: '100%', marginTop: 6 }}
                  options={[
                    { value: 'FR_Ranevskaya_Persona_v1_4', label: 'Раневская' },
                    { value: 'Soul_Core', label: 'Soul Core' },
                    { value: 'Ved_prompt_Masterpiece_v4_3', label: 'Вед' },
                  ]}
                  showSearch
                />
              </div>
              <div>
                <Text strong>Голос</Text>
                <Select
                  loading={voiceLoading}
                  value={voiceId || undefined}
                  onChange={(v) => setVoiceId(v)}
                  style={{ width: '100%', marginTop: 6 }}
                  options={availableVoices.map(v => ({ value: v.id, label: v.display_name || v.id }))}
                  showSearch
                  placeholder={voiceLoading ? 'Загрузка…' : 'Выберите голос'}
                />
              </div>
              <Button type="primary" block loading={voiceLoading} onClick={doApplyVoice}>
                Применить голос
              </Button>
            </Space>
          </Card>
          {/* Статус подписки */}
          <Card title="Подписка" className="mb-4">
            <div className="text-center">
              <div style={{ fontSize: 'var(--sp-font-size-2xl)', marginBottom: 'var(--sp-spacing-md)' }}>
                {getSubscriptionIcon(profileData.subscription_level)}
              </div>
              <Title level={4} style={{ margin: 'var(--sp-spacing-sm) 0' }}>
                {profileData.subscription_level === 'basic' ? 'Базовый' :
                 profileData.subscription_level === 'premium' ? 'Премиум' :
                 profileData.subscription_level === 'corporate' ? 'Корпоративный' : 'Неизвестно'}
              </Title>
              <Tag color={getSubscriptionColor(profileData.subscription_level)}>
                {getSubscriptionIcon(profileData.subscription_level)}
                {profileData.subscription_level === 'basic' ? 'Базовый' : 
                 profileData.subscription_level === 'premium' ? 'Премиум' : 'Корпоративный'}
              </Tag>
              {/* Роли пользователя */}
              {permState?.roles && permState.roles.length > 0 && (
                <div style={{ marginTop: '12px' }}>
                  <Text type="secondary">Роли:</Text>
                  <div style={{ marginTop: 8, display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>
                    {permState.roles.map((r) => (
                      <Tag key={r.name} color={r.name === 'architect' ? 'gold' : r.name === 'admin' ? 'red' : 'blue'}>
                        {r.name}
                      </Tag>
                    ))}
                  </div>
                </div>
              )}
            </div>
            
            <Divider />
            
            <Space direction="vertical" style={{ width: '100%' }}>
              <Button type="primary" block icon={<SettingOutlined />}>
                Управление подпиской
              </Button>
              <Button block icon={<TrophyOutlined />}>
                Преимущества
              </Button>
            </Space>
          </Card>

          {/* Последняя активность */}
          <Card title="Последняя активность" className="mb-4">
            <Space direction="vertical" style={{ width: '100%' }}>
              <div>
                <Text strong>Последний вход:</Text>
                <div style={{ marginTop: 'var(--sp-spacing-sm)' }}>
                  <Text type="secondary">
                    {new Date(profileData.last_seen).toLocaleString('ru-RU')}
                  </Text>
                </div>
              </div>
              
              <div>
                <Text strong>Регистрация:</Text>
                <div style={{ marginTop: 'var(--sp-spacing-sm)' }}>
                  <Text type="secondary">
                    {new Date(profileData.registration_date).toLocaleDateString('ru-RU')}
                  </Text>
                </div>
              </div>
            </Space>
          </Card>

          {/* Быстрые действия */}
          <Card title="Быстрые действия" style={{ boxSizing: 'border-box', width: '100%' }}>
            <Space direction="vertical" style={{ width: '100%' }} size={8}>
              <Button block size="middle" icon={<MessageOutlined />}>Начать чат</Button>
              <Button block size="middle" icon={<FileTextOutlined />}>Мои промпты</Button>
              <Button block size="middle" icon={<SettingOutlined />}>Настройки</Button>
              <Button 
                block
                size="middle"
                type="primary"
                icon={<ReloadOutlined />}
                loading={actionLoading === 'update'}
                onClick={handleUpdateProfile}
              >
                Обновить из Telegram
              </Button>
            </Space>
          </Card>

          {/* Управление профилем */}
          <Card title="Управление профилем" style={{ marginTop: '16px' }}>
            <Space direction="vertical" style={{ width: '100%' }}>
              <Tooltip title="Обновить данные профиля из Telegram">
                <Button 
                  block 
                  icon={<ReloadOutlined />}
                  loading={actionLoading === 'update'}
                  onClick={handleUpdateProfile}
                  type="primary"
                >
                  Обновить профиль
                </Button>
              </Tooltip>
              
              <Tooltip title="Очистить кеш приложения и перезагрузить">
                <Button 
                  block 
                  icon={<ClearOutlined />}
                  loading={actionLoading === 'cache'}
                  onClick={handleClearCache}
                >
                  Очистить кеш
                </Button>
              </Tooltip>
              
              <Tooltip title="Запросить номер телефона через Telegram бота">
                <Button 
                  block 
                  icon={<ContactsOutlined />}
                  loading={actionLoading === 'phone'}
                  onClick={handleRequestPhoneNumber}
                  style={{ marginTop: '8px' }}
                >
                  Добавить телефон
                </Button>
              </Tooltip>
              
              <Tooltip title="Удалить аккаунт и все связанные данные">
                <Button 
                  block 
                  icon={<DeleteOutlined />}
                  loading={actionLoading === 'delete'}
                  onClick={handleDeleteAccount}
                  danger
                  style={{ marginTop: '8px' }}
                >
                  Удалить аккаунт
                </Button>
              </Tooltip>
            </Space>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default UserProfile;
